DROP TABLE IF EXISTS `detalle_planilla`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `detalle_planilla` (
  `id_detalle` int NOT NULL AUTO_INCREMENT,
  `id_planilla` int NOT NULL,
  `id_personal` int NOT NULL,
  `dias_trabajados` int NOT NULL,
  `horas_extras` decimal(5,2) DEFAULT '0.00',
  `monto_horas_extras` decimal(10,2) DEFAULT '0.00',
  `dias_ausencia` int DEFAULT '0',
  `descuento_ausencias` decimal(10,2) DEFAULT '0.00',
  `minutos_tardanza` int DEFAULT '0',
  `descuento_tardanzas` decimal(10,2) DEFAULT '0.00',
  `total_ingresos` decimal(10,2) NOT NULL,
  `total_descuentos` decimal(10,2) NOT NULL,
  `sueldo_neto` decimal(10,2) NOT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_detalle`),
  UNIQUE KEY `unique_planilla_personal` (`id_planilla`,`id_personal`),
  KEY `idx_planilla` (`id_planilla`),
  KEY `idx_personal` (`id_personal`),
  CONSTRAINT `detalle_planilla_ibfk_1` FOREIGN KEY (`id_planilla`) REFERENCES `planilla` (`id_planilla`) ON DELETE CASCADE,
  CONSTRAINT `detalle_planilla_ibfk_2` FOREIGN KEY (`id_personal`) REFERENCES `personal` (`id_personal`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

